with flattened_attrs as (select id, service, host, cast((status_code & 4) != 0 as int) as is_flagged, from_json(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').retries as retry_count, shiftright(status_code, 2) as status_code_high, from_json(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').duration as duration_sec, get_json_object(payload_json, '$.user.id') as user_id from app_logs) select *, row_number() over w_ordered as row_seq, sum(duration_sec) over w_recent as cumulative_duration_sec, row_number() over w_running as seq_no, sum(is_flagged) over w_recent as cumulative_is_flagged, lag(status_code_high, 1, 0) over (partition by service order by retry_count, id) as prev_status_code_high from flattened_attrs window w_ordered as (order by duration_sec, id), w_recent as (partition by host order by is_flagged, id rows between unbounded preceding and current row), w_running as (partition by service order by is_flagged, id)
